import{_ as e,o as a,c as r,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Stage 1 · 持久内核与 MVP","description":"Hearth Stage 1 开发模块：走路骨架、Codex 纵向切片、MVP-1、副作用安全、恢复加固与 Stage 1 发布。","frontmatter":{"title":"Stage 1 · 持久内核与 MVP","description":"Hearth Stage 1 开发模块：走路骨架、Codex 纵向切片、MVP-1、副作用安全、恢复加固与 Stage 1 发布。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-1.md","filePath":"delivery/stage-1.md","lastUpdated":1793761874000}'),d={name:"delivery/stage-1.md"};function i(o,t,h,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<p class="eyebrow">MODULE 1 / 7</p><h1 id="stage-1-·-持久内核与-mvp" tabindex="-1">Stage 1 · 持久内核与 MVP <a class="header-anchor" href="#stage-1-·-持久内核与-mvp" aria-label="Permalink to &quot;Stage 1 · 持久内核与 MVP&quot;">​</a></h1><p class="lead">从原型走到每天可用的本地产品。顺序固定：真实短闭环 → 第一个 Codex 切片 → MVP 收口 → 副作用安全 → 第二任务族 → 恢复与发布。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>Stage 0 的 12 个任务、原型、协议、评测与安全基线可用。</li><li>已确定首个任务族；默认是“研究/文档整理”，若首位用户更依赖代码任务，可替换楔子但保留相同纵向结构。</li><li>Web 是正式产品入口，不允许只靠 CLI、日志或脚本演示。</li></ul><h2 id="开发步骤" tabindex="-1">开发步骤 <a class="header-anchor" href="#开发步骤" aria-label="Permalink to &quot;开发步骤&quot;">​</a></h2><ol><li><strong>交付走路骨架。</strong> 启动 <code>hearthd</code>，接入 SQLite WAL、最小 Event Log、Task/Run 状态机、投影、fake executor、Web 任务列表/详情/创建和 SSE。</li><li><strong>接入第一个真实 Codex 切片。</strong> 完成 Codex adapter、健康检查、一次性 workspace、Task Pack、结构化输出、Artifact、引用/文件验证、事件投影和 Token/延迟采集。</li><li><strong>收口 MVP-1。</strong> 打通创建、查看、取消、重试、审批演练、产物取回、失败恢复和预算异常停止，形成真实窄任务闭环。</li><li><strong>补齐副作用安全骨架。</strong> 实现 Effect Preview、Mandate、Approval、outbox、幂等键、Receipt、撤销/补偿演练和单写者 lease。</li><li><strong>加入第二任务族并加固内核。</strong> 用第二个任务族验证路由、失败分类、预算、并发、重复投递、崩溃恢复和投影一致性。</li><li><strong>完成 Stage 1 发布。</strong> 跑 10 个真实任务，对比全人工与直接 Codex，修复高频失败，补齐安装、备份、升级、导出、安全与评测报告。</li></ol><h2 id="增量拆分" tabindex="-1">增量拆分 <a class="header-anchor" href="#增量拆分" aria-label="Permalink to &quot;增量拆分&quot;">​</a></h2><p>每个增量现在按四层阅读：结果与门槛 → 四个实施工作包 → 工程落点与接口 → 验收演练。工作包可以拆给不同开发者并行，但必须按依赖顺序合并；只完成一个包不等于完成增量。</p><table tabindex="0"><thead><tr><th>增量</th><th>用户可见结果</th><th>完成证据</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-1/d1-1.html">D1.1</a> 可运行走路骨架</td><td>Web 创建任务，刷新或重启后状态仍在</td><td><code>hearthd</code> + SQLite + Event Log + fake executor + SSE</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/d1-2.html">D1.2</a> 首个 Codex 切片</td><td>获得带来源、验证结果和成本的报告</td><td>Task Pack、结构化 Result、Artifact、验证器</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/d1-3.html">D1.3</a> MVP 收口</td><td>创建、取消、重试、审批、产物和恢复都在浏览器完成</td><td>MVP-1 用户故事端到端通过</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/d1-4.html">D1.4</a> 副作用安全骨架</td><td>外部动作有预览、审批、幂等与回执</td><td>outbox、idempotency、Receipt、撤销/补偿演练</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/d1-5.html">D1.5</a> 第二任务族与内核加固</td><td>第二类真实任务可依赖，故障后能恢复</td><td>路由、故障注入、重复投递、恢复测试</td></tr><tr><td><a href="/hearth-os/delivery/stage-1/d1-6.html">D1.6</a> Stage 1 发布</td><td>用户可独立安装、使用、备份和导出</td><td>10 个真实任务、基线对比、安全与评测报告</td></tr></tbody></table><h2 id="mvp-的位置" tabindex="-1">MVP 的位置 <a class="header-anchor" href="#mvp-的位置" aria-label="Permalink to &quot;MVP 的位置&quot;">​</a></h2><p>MVP-1 是 Stage 1 的早期出口，对应 D1.3，不是 Stage 6 的产物。它可以暂时不包含邮件、日历、GUI、主动性和多设备，但必须包含真实执行、持久状态、Web 任务卡、产物、审批演练和失败恢复。</p><h2 id="退出验收" tabindex="-1">退出验收 <a class="header-anchor" href="#退出验收" aria-label="Permalink to &quot;退出验收&quot;">​</a></h2><ul><li>[ ] MVP 能在浏览器中每天使用一个窄任务族。</li><li>[ ] 服务崩溃、刷新或重启后，任务可恢复或明确转人工。</li><li>[ ] 重复投递和重试不会产生重复外部副作用。</li><li>[ ] 任务卡显示状态、产物、成本和下一步；失败原因用户可理解。</li><li>[ ] 至少 10 个真实任务通过人工验收，Token 与人工分钟有基线。</li><li>[ ] 权限边界、秘密保护、kill switch、备份和数据导出可用。</li></ul><h2 id="本模块不做" tabindex="-1">本模块不做 <a class="header-anchor" href="#本模块不做" aria-label="Permalink to &quot;本模块不做&quot;">​</a></h2><ul><li>不做邮件、日历、桌面 GUI、主动循环或多设备。</li><li>不先扩展执行器数量而牺牲恢复、审批和界面完整性。</li><li>不用演示脚本替代真实 Codex 执行与验证。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>进入 <a href="/hearth-os/delivery/stage-2.html">Stage 2 · Personal Operator</a>，从只读连接器开始扩展日常内容工作。</p>',18)])])}const u=e(d,[["render",i]]);export{p as __pageData,u as default};
